import{_ as a,C as s,o as r,c as i,a2 as t,E as n}from"./chunks/framework.Cu3jFwFD.js";const m=JSON.parse('{"title":"Hermes Express — Game Design Document","description":"","frontmatter":{},"headers":[],"relativePath":"GDD.md","filePath":"GDD.md","lastUpdated":1795074279000}'),o={name:"GDD.md"};function c(l,e,h,p,u,g){const d=s("CoreLoop");return r(),i("div",null,[e[0]||(e[0]=t(`<h1 id="hermes-express-—-game-design-document" tabindex="-1">Hermes Express — Game Design Document <a class="header-anchor" href="#hermes-express-—-game-design-document" aria-label="Permalink to &quot;Hermes Express — Game Design Document&quot;">​</a></h1><p><strong>Version:</strong> 0.8 · <strong>Updated:</strong> 2026-11-17 · <a href="#feature-index">Features</a> · <a href="#decisions">Decisions</a> · <a href="#change-log">Change log</a></p><p>This document and the feature notes in <code>features/</code> are the single source of truth for Hermes Express&#39;s design (<a class="decision-ref" href="/hex-gdd/GDD#d-024">D‑024</a>). If the game or any other document disagrees with them, they win; change them first, then the game.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>A survival delivery game where your cargo changes how you drive. Hermes, the messenger god demoted to a human courier, delivers the gods&#39; packages in an old van through a modern Mount Olympus. Each short day he takes jobs at will, then decides whether to run home or push into a paid overtime hunted by Zeus&#39;s storm. Three days of work have to make one profit quota; meeting it earns a race against Iris on Charon&#39;s boss day. Missing it, or losing the race, restarts the run from Day 1.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Genre and camera</td><td>Roguelite arcade delivery driving, full 3D, free third-person chase camera (like GTA)</td></tr><tr><td>Audience</td><td>Casual to core PC players who like short runs and comedy</td></tr><tr><td>Platforms and input</td><td>macOS, keyboard: 4 drive keys plus E to pick up and deliver</td></tr><tr><td>Session</td><td>One run = 3 shifts of 60 s plus a 120 s boss shift plus Garage time, about 6–8 min (<a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a>)</td></tr><tr><td>Engine</td><td>Unity 6 (6000.6.5f1), URP; the current build is a prototype</td></tr><tr><td>Scope</td><td>MVP: one map (Olympus), one run shape, vertical slice first</td></tr><tr><td>References</td><td>Crazy Taxi (random pickup and drop-off model); slot-machine and roguelike run structure</td></tr></tbody></table><h2 id="pillars" tabindex="-1">Pillars <a class="header-anchor" href="#pillars" aria-label="Permalink to &quot;Pillars&quot;">​</a></h2><ol><li><strong>Push your luck.</strong> Every day the player weighs going home on time against one more package or overtime, and taking a smuggled package that may be a scam but pays big. Rules out: safe, fixed routes with no temptation.</li><li><strong>Simple to play.</strong> Four drive keys plus E. Rules out: a second action layer that needs explaining.</li><li><strong>Whimsical and comedic.</strong> Humor comes from the blessing system and the scam packages, amplified by a cartoon low-poly style. Rules out: grim or realistic tone.</li><li><strong>Bro thinks he&#39;s smart.</strong> Overtime pays ×1.5, and the player always believes there is time for one more delivery before Zeus&#39;s storm catches up. Greed is the joke: the big money is right there, and so is the lightning. Rules out: any safe way to bank overtime money before reaching HQ.</li></ol><h2 id="core-loop" tabindex="-1">Core loop <a class="header-anchor" href="#core-loop" aria-label="Permalink to &quot;Core loop&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Garage (repair, pick a card) → shift: pick up → deliver → money</span></span>
<span class="line"><span>   → clock ends: go home or overtime (storm hunts) → report → quota check after Day 3 → boss → ending</span></span></code></pre></div><ul><li><strong>Seconds:</strong> drive, stop in a marker, press E (<a href="./features/packages/design">packages</a>); dodge crashes and lightning (<a href="./features/damage-and-repair/design">damage-and-repair</a>).</li><li><strong>Minutes:</strong> one shift of 60 s, then the choice between home and overtime (<a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a>).</li><li><strong>Session:</strong> three days, a quota gate on Day 3, a boss day (<a href="./features/run-and-quota/design">run-and-quota</a>, <a href="./features/boss-charon/design">boss-charon</a>); between days, the Garage (<a href="./features/upgrades/design">upgrades</a>).</li></ul><h2 id="feature-index" tabindex="-1">Feature index <a class="header-anchor" href="#feature-index" aria-label="Permalink to &quot;Feature index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th><th>Scope</th><th>Summary</th><th>Docs</th></tr></thead><tbody><tr><td>Run and quota</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>3 normal days, one run quota checked after Day 3, then the boss; fail = restart</td><td><a href="./features/run-and-quota/design">design</a></td></tr><tr><td>Day cycle, overtime and storm</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>60 s shift, automatic overtime at ×1.5 pay, Zeus&#39;s storm hunts the van and escalates until it kills</td><td><a href="./features/day-cycle-and-storm/design">design</a></td></tr><tr><td>Packages</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Safe, Zeus god package, Chance (scam); unlimited cargo</td><td><a href="./features/packages/design">design</a></td></tr><tr><td>Damage and repair</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>10 visible HP, scam and crashes cost HP, paid repair in the Garage, wreck fails the day</td><td><a href="./features/damage-and-repair/design">design</a></td></tr><tr><td>Upgrades</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Free pick of 3 cards (Clean/Gamble), reroll, relic shelf, bought with cash</td><td><a href="./features/upgrades/design">design</a></td></tr><tr><td>Boss day: Charon&#39;s soul race</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Race Iris to 12 souls on Day 4</td><td><a href="./features/boss-charon/design">design</a></td></tr><tr class="row-cut"><td>Combo</td><td><span class="status-badge status-cut">CUT</span></td><td>—</td><td>Delivery combo multiplier; cut by owner</td><td><a href="./features/combo/design">design</a></td></tr><tr><td>Driving</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Arcade steer, gas, brake + E; optional drift (Space, handling only) and nitro (Shift, refills from deliveries and over time)</td><td><a href="./features/driving/design">design</a></td></tr><tr><td>Trials</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Before Day 2 and 3, pick 1 of 3 trials: danger (lightning), value (pay), intensity (jobs); Day 1 fixed Standard</td><td><a href="./features/trials/design">design</a></td></tr><tr><td>First-run tutorial</td><td><span class="status-badge status-idea">IDEA</span></td><td>MVP</td><td>Day 1 script: two Safe packages, then Zeus, scripted strikes, blessing lost</td><td>—</td></tr><tr><td>Hazards</td><td><span class="status-badge status-designed">DESIGNED</span></td><td>MVP</td><td>Modular catalogue: strike, big strike, boundary, crash; each with telegraph, effect, counters</td><td><a href="./features/hazards/design">design</a></td></tr><tr><td>Audio</td><td><span class="status-badge status-idea">IDEA</span></td><td>MVP</td><td>Sound and music list by trigger: music, van, packages, hazards, world, UI and voice; mix buses</td><td><a href="./features/audio/design">design</a></td></tr><tr><td>Map: Olympus</td><td><span class="status-badge status-idea">IDEA</span></td><td>MVP</td><td>One map, HQ, houses, palaces, Electrical Plant; a new, smaller, more city-like map replaces the prototype&#39;s; layout not specified</td><td>—</td></tr></tbody></table><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2><ol><li><strong>M1, core loop spec&#39;d and greybox:</strong> run-and-quota, day-cycle-and-storm, packages, damage-and-repair · done when a player can finish Day 1–3 and see a pass or fail verdict on the Day 3 report.</li><li><strong>M2, full run:</strong> upgrades and boss-charon · done when a player can win or lose the Charon race and see the ending or game over.</li></ol><h2 id="screens-and-flow" tabindex="-1">Screens and flow <a class="header-anchor" href="#screens-and-flow" aria-label="Permalink to &quot;Screens and flow&quot;">​</a></h2>`,16)),n(d),e[1]||(e[1]=t(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Main menu → Opening cutscene → Garage (Day 1)</span></span>
<span class="line"><span>Garage → Start → choose trial (Day 2–3; Day 1 fixed Standard) → shift</span></span>
<span class="line"><span>   → clock ends: go home, or overtime (a choice made by driving, not a menu)</span></span>
<span class="line"><span>   → report</span></span>
<span class="line"><span>      Day 1–2            → Garage (next day)</span></span>
<span class="line"><span>      Day 3, quota met   → Garage → Start → boss shift (no trial)</span></span>
<span class="line"><span>      Day 3, quota missed → game-over summary → cutscene → Try Again → Day 1</span></span>
<span class="line"><span>Boss: Hermes wins → ending · Iris wins → game-over summary → cutscene → Try Again → Day 1</span></span></code></pre></div><p>Owners: Garage = <a href="./features/upgrades/design">upgrades</a> and <a href="./features/damage-and-repair/design">damage-and-repair</a>; trial = <a href="./features/trials/design">trials</a>; shift and overtime = <a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a>; report, game over = <a href="./features/run-and-quota/design">run-and-quota</a>; boss and ending = <a href="./features/boss-charon/design">boss-charon</a>.</p><h2 id="direction" tabindex="-1">Direction <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;Direction&quot;">​</a></h2><ul><li><strong>Narrative:</strong> Hermes once delivered the wrong package to the wrong god; Zeus took his godhood and his winged sandals and made him a courier for all the gods. Hera has her own messenger now, Iris, who is also his rival on the boss day. The quota is atonement; the storm is Zeus disliking couriers working after hours; the scam packages are Hermes taking grey-area jobs because he is desperate. Opening and game-over scenes tell this in short visual-novel pages; the ending is a four-line scene with Charon and Hermes.</li><li><strong>Art:</strong> low-poly cartoon, visual direction C (modern), Greek identity carried by landmarks and ornaments.</li><li><strong>Camera and controls:</strong> third-person chase camera behind the van, free to orbit (mouse / right stick) and easing back behind the van when the player lets go, like GTA (<a class="decision-ref" href="/hex-gdd/GDD#d-077">D‑077</a>). Four drive keys plus E.</li><li><strong>Feedback:</strong> a health bar and smoke show damage; a marker above each package shows its type, pay and direction.</li><li><strong>Audio:</strong> engine sound, UI and lightning effects exist in the prototype; no audio design is written yet.</li></ul><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><p>IDs run in sequence and are never reused. A superseded decision stays in the table, marked &quot;→ superseded by D-n&quot;. Dates before <a class="decision-ref" href="/hex-gdd/GDD#d-024">D‑024</a> are the original Indonesian log, translated.</p><table tabindex="0"><thead><tr><th>ID</th><th>Date</th><th>Decision</th><th>Alternatives considered</th><th>Why</th><th>Affects</th></tr></thead><tbody><tr id="d-001"><td><span class="decision-id">D‑001</span></td><td>2026-10-12</td><td>Quota, not open progression</td><td>open progression</td><td>A showcase needs a session that ends; quota makes push-your-luck contextual</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-002"><td><span class="decision-id">D‑002</span></td><td>2026-10-13</td><td>Setting: modern Olympus (urban fantasy)</td><td>—</td><td>The gig-economy comedy reads at once; the car makes sense</td><td>—</td></tr><tr id="d-003"><td><span class="decision-id">D‑003</span></td><td>2026-10-13</td><td>Roguelike on Olympus; other regions are vision</td><td>—</td><td>The MVP does not promise content that does not exist</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-004"><td><span class="decision-id">D‑004</span></td><td>2026-10-13</td><td>Points = income</td><td>three kinds of &quot;points&quot;</td><td>Avoids mixing three point types</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-005" class="row-superseded"><td><span class="decision-id">D‑005</span></td><td>2026-10-13</td><td>One wallet: upgrades reduce the balance</td><td>—</td><td>Invest vs save adds decisions → partly superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-022">D‑022</a></td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-006" class="row-superseded"><td><span class="decision-id">D‑006</span></td><td>2026-10-13</td><td>Minotaur: hybrid knockback physics, fake-animation fallback</td><td>—</td><td>Funny outcome without breaking arcade driving → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-023">D‑023</a></td><td>—</td></tr><tr id="d-007"><td><span class="decision-id">D‑007</span></td><td>2026-10-14</td><td>MC = demoted Hermes; quota = atonement</td><td>—</td><td>Narrative explains quota, driving and grey areas</td><td>Direction</td></tr><tr id="d-008"><td><span class="decision-id">D‑008</span></td><td>2026-10-15</td><td>Visual direction C (modern)</td><td>—</td><td>Greek identity through landmarks and ornaments</td><td>Direction</td></tr><tr id="d-009"><td><span class="decision-id">D‑009</span></td><td>2026-10-15</td><td>Zeus package destination = Electrical Plant</td><td>—</td><td>The way home passes through the lightning field</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-010" class="row-superseded"><td><span class="decision-id">D‑010</span></td><td>2026-10-15</td><td>Locked isometric camera</td><td>—</td><td>Map and telegraphs always read from the same angle → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-077">D‑077</a></td><td>Direction</td></tr><tr id="d-011" class="row-superseded"><td><span class="decision-id">D‑011</span></td><td>2026-10-15</td><td>Feature complete 25 Oct, plan B checkpoint 22 Oct</td><td>—</td><td>TypeCaster insight: half the time left is buffer → obsolete, dates passed</td><td>—</td></tr><tr id="d-012"><td><span class="decision-id">D‑012</span></td><td>2026-10-16</td><td>Full 3D</td><td>2D</td><td>Native sorting, collision, lighting, physics; avoids 2D/3D cohesion problems</td><td>Direction</td></tr><tr id="d-013" class="row-superseded"><td><span class="decision-id">D‑013</span></td><td>2026-10-21</td><td>Daily quota, 7 days, miss = game over</td><td>—</td><td>A clear roguelike; pressure every day → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-025">D‑025</a></td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-014"><td><span class="decision-id">D‑014</span></td><td>2026-10-21</td><td>Angry meter removed</td><td>—</td><td>Escalation from hazard location and time is enough</td><td>—</td></tr><tr id="d-015" class="row-superseded"><td><span class="decision-id">D‑015</span></td><td>2026-10-21</td><td>HP removed; damage = 3 states + surprise bill</td><td>—</td><td>One losing condition; carelessness is paid in money → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-026">D‑026</a></td><td><a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-016"><td><span class="decision-id">D‑016</span></td><td>2026-10-21</td><td>Three package categories: Safe, Skill, Chance</td><td>—</td><td>Three kinds of risk: safe, skill, chance</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-017" class="row-superseded"><td><span class="decision-id">D‑017</span></td><td>2026-10-21</td><td>Smuggled packages show a visible scam %; scam = damage</td><td>—</td><td>A bet with full information, so players blame their own decision → visible % superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a></td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-018"><td><span class="decision-id">D‑018</span></td><td>2026-10-21</td><td>HQ only spawn + upgrade; random packages, pickup by stopping + E</td><td>—</td><td>Spontaneous decisions; a clear HQ/map split</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-019"><td><span class="decision-id">D‑019</span></td><td>2026-10-21</td><td>Must return to HQ; overtime hunted by Zeus&#39;s storm</td><td>—</td><td>The way home matters again; the Zeus hook stays whole; the storm reuses lightning</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-020" class="row-superseded"><td><span class="decision-id">D‑020</span></td><td>2026-10-21</td><td>God packages take 2 slots</td><td>—</td><td>The price of holding the blessing reads without extra UI → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a></td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-021"><td><span class="decision-id">D‑021</span></td><td>2026-10-21</td><td>Dionysus deferred</td><td>—</td><td>Scope focus; curse replaced by scam</td><td>—</td></tr><tr id="d-022"><td><span class="decision-id">D‑022</span></td><td>2026-10-23</td><td>Upgrades = pick 1 of 3 free cards, Clean and Gamble, reroll and extra card paid from workshop cash</td><td>fixed Capacity 3→4→5 upgrade; &quot;one wallet&quot;</td><td>Each run gets a different build, and upgrades join push-your-luck</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-023"><td><span class="decision-id">D‑023</span></td><td>2026-10-27</td><td>Plan B: lightning is the only hazard; Minotaur cut</td><td>keep Minotaur</td><td>Scope; recorded in the project&#39;s planning notes. Smuggled packages stay in the design (see <a class="decision-ref" href="/hex-gdd/GDD#d-027">D‑027</a>)</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-024"><td><span class="decision-id">D‑024</span></td><td>2026-11-17</td><td>Spec-driven: this GDD and <code>features/</code> are the source of truth; the Unity build is a prototype</td><td>GDD as an after-the-fact description of the build</td><td>Design decisions come first; the prototype supplies starting numbers</td><td>all</td></tr><tr id="d-025"><td><span class="decision-id">D‑025</span></td><td>2026-11-17</td><td>Run = 3 normal days; one run quota checked after Day 3; pass → Day 4 boss, fail → game over</td><td>7 days with a daily rising quota; 3 days + boss with no gate</td><td>The run stays short; a single gate makes Day 3 the decision. 7 days becomes a later option</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-026"><td><span class="decision-id">D‑026</span></td><td>2026-11-17</td><td>Visible HP (10), carried between days, paid repair in the Garage</td><td>hidden damage with a report bill (<a class="decision-ref" href="/hex-gdd/GDD#d-015">D‑015</a>)</td><td>Every damage source is readable, which keeps losses fair</td><td><a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-027"><td><span class="decision-id">D‑027</span></td><td>2026-11-17</td><td>A failed Chance (scam) delivery deals HP damage</td><td>scam only costs the pay</td><td>Restores the stakes of <a class="decision-ref" href="/hex-gdd/GDD#d-017">D‑017</a>; the prototype&#39;s scam only lost the payout</td><td><a href="./features/packages/design">packages</a>, <a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-028"><td><span class="decision-id">D‑028</span></td><td>2026-11-17</td><td>Cargo is unlimited; no slot limit, no 2-slot Zeus</td><td>3 slots with capacity cards</td><td>Owner decision; capacity cards and the Zeus slot price are removed</td><td><a href="./features/packages/design">packages</a>, <a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-029"><td><span class="decision-id">D‑029</span></td><td>2026-11-17</td><td>No combo multiplier</td><td>keep the prototype&#39;s ×0.25 per step, max ×3</td><td>Owner decision; the quota must be re-tuned</td><td><a href="./features/combo/design">combo</a>, <a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-030"><td><span class="decision-id">D‑030</span></td><td>2026-11-17</td><td>Normal shift stays 60 s; a run is about 6–8 min</td><td>90 s shifts (about 10 min); 180 s shifts (the old 15 min target)</td><td>Owner decision; short runs suit the slice and repeated playtests. The old 15 min target is dropped</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-031"><td><span class="decision-id">D‑031</span></td><td>2026-11-17</td><td>Cash = all banked net income; spending never lowers profit</td><td>only surplus above the daily pace; one wallet (<a class="decision-ref" href="/hex-gdd/GDD#d-005">D‑005</a>)</td><td>Repair and relics stay affordable without slowing the quota</td><td><a href="./features/run-and-quota/design">run-and-quota</a>, <a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-032"><td><span class="decision-id">D‑032</span></td><td>2026-11-17</td><td>No mid-run save: quitting to the menu loses the run</td><td>autosave in the Garage</td><td>A run is short; saves are not worth the MVP cost</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-033"><td><span class="decision-id">D‑033</span></td><td>2026-11-17</td><td>Game over first shows the cause and the run totals, then the cutscene</td><td>cutscene only</td><td>The player must see why the run ended (roguelike rule)</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-034" class="row-superseded"><td><span class="decision-id">D‑034</span></td><td>2026-11-17</td><td>Chance packages use three fixed risk tiers: 10 / 25 / 50%</td><td>random 0–100% (prototype); random within 5–60%</td><td>Readable at a glance; no absurd offers. Tiers stay; showing them → superseded by <a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a></td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-035"><td><span class="decision-id">D‑035</span></td><td>2026-11-17</td><td>A failed Chance delivery costs 2 HP</td><td>1 HP; scaled by tier</td><td>The loss must bite: about $60 of repair</td><td><a href="./features/packages/design">packages</a>, <a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-036"><td><span class="decision-id">D‑036</span></td><td>2026-11-17</td><td>Zeus pays a medium amount, about 2× Safe</td><td>about 5× Safe</td><td>The new map is smaller and city-like, so the detour is short</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-037"><td><span class="decision-id">D‑037</span></td><td>2026-11-17</td><td>A failed Chance delivery may wreck the van</td><td>HP stops at 1</td><td>Risk and HP are both visible; the player owns the choice</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-038"><td><span class="decision-id">D‑038</span></td><td>2026-11-17</td><td>The report shows end-of-day HP only, no breakdown by source</td><td>one row per damage source</td><td>Keeps the report short; in-shift feedback names the source</td><td><a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-039"><td><span class="decision-id">D‑039</span></td><td>2026-11-17</td><td>Repair is full only, one button</td><td>partial repair per HP</td><td>Simple; one decision per visit</td><td><a href="./features/damage-and-repair/design">damage-and-repair</a></td></tr><tr id="d-040"><td><span class="decision-id">D‑040</span></td><td>2026-11-17</td><td>Cash buys relics (plus repair and rerolls); no extra card for cash</td><td>extra card only (<a class="decision-ref" href="/hex-gdd/GDD#d-022">D‑022</a>); both</td><td>The relic shelf is built and playable</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-041"><td><span class="decision-id">D‑041</span></td><td>2026-11-17</td><td>The Cargo theme becomes a Delivery theme (Wide Dock, Blessed Courier)</td><td>drop to three themes</td><td>Keeps four themes after capacity cards were removed (<a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a>)</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-042"><td><span class="decision-id">D‑042</span></td><td>2026-11-17</td><td>No Zeus ultimate; overtime lightning escalates absurdly until it kills the van</td><td>a fixed cutoff after 30 / 45 / 60 s</td><td>Owner decision; the end comes from the storm itself, so greed is punished gradually</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-043"><td><span class="decision-id">D‑043</span></td><td>2026-11-17</td><td>Big Lightning Rod&#39;s price: the shift is 10 s shorter</td><td>light lightning during the shift</td><td>The old &quot;storm 1 hour earlier&quot; has no clock to refer to</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-044"><td><span class="decision-id">D‑044</span></td><td>2026-11-17</td><td>Day 1: Safe + Zeus; Day 2: + Chance; Day 3: everything, in every run</td><td>everything from Day 1 after the tutorial</td><td>Teaches one system per day in a 3-day run</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-045"><td><span class="decision-id">D‑045</span></td><td>2026-11-17</td><td>No fine for undelivered packages</td><td>keep 10% per package</td><td>With unlimited cargo it would read as a hidden punishment</td><td><a href="./features/run-and-quota/design">run-and-quota</a></td></tr><tr id="d-046"><td><span class="decision-id">D‑046</span></td><td>2026-11-17</td><td>Trials are MVP: pick 1 of 3 before Day 2 and Day 3; Day 1 always Standard</td><td>trials from Day 1; trials later</td><td>The owner&#39;s day flow; Day 1 stays readable for new players and the tutorial</td><td><a href="./features/trials/design">trials</a></td></tr><tr id="d-047"><td><span class="decision-id">D‑047</span></td><td>2026-11-17</td><td>Danger sets shift lightning: 1 = only in the lightning area, 2 = on the map lightly, 3 = on the map busily</td><td>danger only scales the overtime storm</td><td>Danger is felt in every shift, not only by players who work overtime</td><td><a href="./features/trials/design">trials</a>, <a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-048"><td><span class="decision-id">D‑048</span></td><td>2026-11-17</td><td>Intensity = number of jobs, a reward</td><td>intensity as pressure (traffic, tighter zones)</td><td>Keeps danger as the only price of a trial</td><td><a href="./features/trials/design">trials</a>, <a href="./features/packages/design">packages</a></td></tr><tr id="d-049"><td><span class="decision-id">D‑049</span></td><td>2026-11-17</td><td>No trial on the boss day; fixed setup</td><td>trials on the boss day too</td><td>The race is challenge enough; value means nothing without money</td><td><a href="./features/trials/design">trials</a>, <a href="./features/boss-charon/design">boss-charon</a></td></tr><tr id="d-050"><td><span class="decision-id">D‑050</span></td><td>2026-11-17</td><td>Lightning Rod = a shield that absorbs one strike and refills 20 s after use</td><td>refill on each delivery; refill at HQ</td><td>The old &quot;1× per day&quot; was used up unseen and felt useless</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-051"><td><span class="decision-id">D‑051</span></td><td>2026-11-17</td><td>The shield is shown on the HUD with a refill ring</td><td>only an effect when it absorbs</td><td>Players can plan around a shield they can see</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-052"><td><span class="decision-id">D‑052</span></td><td>2026-11-17</td><td>Big Lightning Rod = shield refills twice as fast; price stays shift −10 s</td><td>two shields; full immunity at danger 1–2</td><td>Same mechanic, stronger, with a readable price</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-053"><td><span class="decision-id">D‑053</span></td><td>2026-11-17</td><td>Relic &quot;Lightning Rod&quot; becomes Grounding Coil: the shield also blocks big strikes</td><td>faster refill; remove the relic</td><td>A different function, not just a bigger number</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-054"><td><span class="decision-id">D‑054</span></td><td>2026-11-17</td><td>Trials are rolled with a reward budget per danger (3 / 4 / 5–6)</td><td>hand-made templates; only &quot;danger 3 needs one +++&quot;</td><td>No trial is strictly worse; danger +++ always pays</td><td><a href="./features/trials/design">trials</a></td></tr><tr id="d-055"><td><span class="decision-id">D‑055</span></td><td>2026-11-17</td><td>Drift is in the design as handling only, no reward</td><td>drift fills nitro</td><td>Keeps drift a skill, not a resource loop</td><td><a href="./features/driving/design">driving</a></td></tr><tr id="d-056"><td><span class="decision-id">D‑056</span></td><td>2026-11-17</td><td>Nitro refills from deliveries and slowly over time</td><td>also from drift</td><td>Same as the prototype; ties boosts to doing the job</td><td><a href="./features/driving/design">driving</a></td></tr><tr id="d-057"><td><span class="decision-id">D‑057</span></td><td>2026-11-17</td><td>The &quot;Simple to play&quot; pillar is unchanged: 4 drive keys + E; drift and nitro are optional extras</td><td>rewrite the pillar to include Space and Shift</td><td>The game stays finishable with the core keys</td><td><a href="./features/driving/design">driving</a></td></tr><tr id="d-058"><td><span class="decision-id">D‑058</span></td><td>2026-11-17</td><td>HQ ends the day only after the shift clock reaches 0</td><td>end the day early at any time</td><td>No early bail-out; the shift is always played in full</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-059"><td><span class="decision-id">D‑059</span></td><td>2026-11-17</td><td>Job mix: one Zeus job per normal day; from Day 2, 25% of new jobs are Chance (scam); the rest Safe</td><td>Zeus repeatable (max 1 open); Zeus only on Day 1</td><td>Zeus stays a special moment each day; scam is common but not dominant</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-060"><td><span class="decision-id">D‑060</span></td><td>2026-11-17</td><td>E works anywhere inside a marker&#39;s zone at any speed; no stopping</td><td>slow below 2 m/s; hold E 0.5 s</td><td>The game is fast-paced; stopping would be friction</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-061"><td><span class="decision-id">D‑061</span></td><td>2026-11-17</td><td>Chance (scam) pay = a Safe pay roll × 2 / 4 / 9 by tier</td><td>fixed ranges per tier</td><td>One formula, tied to the Safe economy</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-062"><td><span class="decision-id">D‑062</span></td><td>2026-11-17</td><td>Shift lightning: danger 1 every 3 s inside each lightning area; danger 2 every 6 s and danger 3 every 2.5 s at random points within 40 m of the van</td><td>random points over the whole map; softer or harder rates</td><td>The player always sees and feels the chosen danger</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a>, <a href="./features/trials/design">trials</a></td></tr><tr id="d-063"><td><span class="decision-id">D‑063</span></td><td>2026-11-17</td><td>Overtime escalation: after the 25 s ramp, every 10 s gap ×0.8 (min 0.25 s), +1 simultaneous strike, big-strike interval ×0.8</td><td>every 5 s; every 15 s</td><td>A skilled driver cannot survive past about 50–60 s of overtime</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-064"><td><span class="decision-id">D‑064</span></td><td>2026-11-17</td><td>Every normal strike costs 2 HP, in the shift and in overtime</td><td>1 HP in the shift, 2 HP in overtime</td><td>One value for one look</td><td><a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-065"><td><span class="decision-id">D‑065</span></td><td>2026-11-17</td><td>Taking the free card is mandatory (Start is locked until one is taken); a wrecked day still gives the card</td><td>skippable pick; no card after a wreck</td><td>A free card has no downside to refuse; a wreck is punished enough</td><td><a href="./features/upgrades/design">upgrades</a></td></tr><tr id="d-066"><td><span class="decision-id">D‑066</span></td><td>2026-11-17</td><td>Boss day spawns only Safe packages, shown as souls</td><td>all package types</td><td>The race is about routes and speed</td><td><a href="./features/boss-charon/design">boss-charon</a></td></tr><tr id="d-067"><td><span class="decision-id">D‑067</span></td><td>2026-11-17</td><td>Shift HUD: time bar / OVERTIME, today&#39;s earnings, HP + shield, nitro, direction arrow; no quota bar</td><td>also a quota pace bar</td><td>Keep the HUD to what changes the next decision</td><td>hud</td></tr><tr id="d-068"><td><span class="decision-id">D‑068</span></td><td>2026-11-17</td><td>Keyboard and gamepad in the MVP; gamepad uses the racing layout: RT gas, LT brake, left stick steer, A pick up / deliver, B drift, LB nitro, Start pause</td><td>keyboard only; Forza-style (A drift, X interact); Hot Wheels-style (A nitro)</td><td>Common racing convention; the core action stays on the main face button</td><td>ui-input</td></tr><tr id="d-069"><td><span class="decision-id">D‑069</span></td><td>2026-11-17</td><td>Garage = one hub screen with the van in the middle; report and card draw open as overlays in order</td><td>a step-by-step wizard of screens</td><td>Matches the prototype, which already works</td><td>ui-screens</td></tr><tr id="d-070"><td><span class="decision-id">D‑070</span></td><td>2026-11-17</td><td>Feedback kept: scam slot machine and wreck slow motion, speed feel (FOV, wind lines, camera lean), Hermes&#39;s start-of-day bark. Cut: slow motion and camera swing on pickup</td><td>keep the pickup reveal</td><td>Slow motion stays special; pickup must not break a fast-paced flow</td><td>ui-feedback</td></tr><tr id="d-071"><td><span class="decision-id">D‑071</span></td><td>2026-11-17</td><td>MVP UI is graybox only; the spec carries HTML/CSS graybox wireframes, not final art</td><td>finished UI art</td><td>Programmers can build and test the flow before any art exists</td><td>ui-screens</td></tr><tr id="d-072"><td><span class="decision-id">D‑072</span></td><td>2026-11-17</td><td>Pause menu: Resume, Controls, Settings, Quit to menu (with a confirm)</td><td>Restart run; Resume and Quit only</td><td>Covers the basics without a mid-run restart shortcut</td><td>ui-screens</td></tr><tr id="d-073"><td><span class="decision-id">D‑073</span></td><td>2026-11-17</td><td>Settings: master / music / effects volume; fullscreen or windowed and resolution. No rebinding, no vibration</td><td>also vibration toggle; tutorial toggle</td><td>The minimum a Mac game needs</td><td>ui-screens, ui-input</td></tr><tr id="d-074"><td><span class="decision-id">D‑074</span></td><td>2026-11-17</td><td>In-game text is English only</td><td>Indonesian; both with a language switch</td><td>One language for the MVP, same as the docs</td><td>ui-screens</td></tr><tr id="d-075"><td><span class="decision-id">D‑075</span></td><td>2026-11-17</td><td>Package markers show only a type box (blue Safe, red devil Chance, gold crown Zeus) and 1–3 pay coins; the Chance failure chance is hidden (no skulls, no %)</td><td>skulls; failure % on the marker</td><td>User testing: players read only the money and ignored the risk icons</td><td><a href="./features/packages/design">packages</a>, ui-screens</td></tr><tr id="d-076"><td><span class="decision-id">D‑076</span></td><td>2026-11-17</td><td>One package per E press; several packages in reach need one press each (deliver first, then nearest pickup)</td><td>one press handles every package in reach</td><td>Each pickup and delivery stays a deliberate action, also for markers placed close together</td><td><a href="./features/packages/design">packages</a></td></tr><tr id="d-077"><td><span class="decision-id">D‑077</span></td><td>2026-11-17</td><td>Camera: free third-person chase camera behind the van (orbit with mouse / right stick, eases back behind), like GTA</td><td>locked isometric (<a class="decision-ref" href="/hex-gdd/GDD#d-010">D‑010</a>)</td><td>Owner pivot; speed and the city read better from behind the wheel</td><td>Direction, <a href="./features/hazards/design">hazards</a></td></tr><tr id="d-078"><td><span class="decision-id">D‑078</span></td><td>2026-11-17</td><td>Pillar &quot;Bro thinks he&#39;s smart&quot; is about overtime greed: one more delivery before the storm</td><td>clever package and route choices</td><td>Overtime is where the game&#39;s biggest risk and reward meet</td><td>Pillars, <a href="./features/day-cycle-and-storm/design">day-cycle-and-storm</a></td></tr><tr id="d-079"><td><span class="decision-id">D‑079</span></td><td>2026-11-17</td><td>Damage states lower top speed: dented −10%, badly damaged −25%</td><td>HP only costs money</td><td>Damage is felt while driving, not only in the Garage</td><td><a href="./features/damage-and-repair/design">damage-and-repair</a>, <a href="./features/driving/design">driving</a></td></tr><tr id="d-080"><td><span class="decision-id">D‑080</span></td><td>2026-11-17</td><td>Hazards are a modular catalogue (one module per hazard); schedules stay in trials and day-cycle and refer to hazards by id</td><td>hazard rules spread across the features that spawn them</td><td>One home per hazard; new hazards plug in without touching schedulers</td><td><a href="./features/hazards/design">hazards</a></td></tr><tr id="d-081"><td><span class="decision-id">D‑081</span></td><td>2026-11-19</td><td>Audio is one spec listing every sound and music cue by trigger, with mix buses and priority rules</td><td>sound rows spread inside each feature</td><td>One checklist for the audio work; triggers reuse the event names from the other specs</td><td><a href="./features/audio/design">audio</a></td></tr></tbody></table><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><strong>Assumptions to confirm:</strong> design questions were settled on 2026-11-17 (<a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-045">D‑045</a>). What remains are prototype tuning numbers: run quota $600, 120 s boss shift, Safe pay and the 0.65 multiplier, open pickups and spawn interval, storm numbers, HP amounts and repair price, Gamble chance, reroll price, card and relic numbers, Iris&#39;s pace; plus the audience and the time bar on the HUD.</li><li><strong>Re-tune after the combo cut:</strong> the prototype&#39;s income and quota were tuned with bonuses up to ×3. How to find out: playtest Day 1–3 without combo and compare profit to the quota.</li><li><strong>Push your luck without capacity:</strong> unlimited cargo removes the old lever (Zeus&#39;s 2 slots). Remaining levers are overtime, scam odds and the Zeus detour. How to find out: playtest whether picking up Zeus is still a decision.</li><li><strong>Reward on a failed run:</strong> a restart gives nothing; decide on a small reward (record, light unlock) later.</li><li><strong>Other open items from the old GDD:</strong> third hazard (needed or not); anti-pillars; playtest success criteria; a tuning-numbers table (this version puts numbers in each feature note).</li></ul><h2 id="change-log" tabindex="-1">Change log <a class="header-anchor" href="#change-log" aria-label="Permalink to &quot;Change log&quot;">​</a></h2><p><strong>0.8 (2026-11-17):</strong> Chase camera (<a class="decision-ref" href="/hex-gdd/GDD#d-077">D‑077</a>), overtime-greed pillar (<a class="decision-ref" href="/hex-gdd/GDD#d-078">D‑078</a>), damage slows the van (<a class="decision-ref" href="/hex-gdd/GDD#d-079">D‑079</a>), hazards catalogue (<a class="decision-ref" href="/hex-gdd/GDD#d-080">D‑080</a>). <strong>0.7 (2026-11-17):</strong> One package per E press (<a class="decision-ref" href="/hex-gdd/GDD#d-076">D‑076</a>). <strong>0.6 (2026-11-17):</strong> Package markers: type box + pay coins, Chance risk hidden after user testing (<a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a>). <strong>0.5 (2026-11-17):</strong> UI guide for UI programmers: ui-screens with graybox wireframes, ui-feedback, ui-input, and an Events (logic → UI) section in every gameplay spec (<a class="decision-ref" href="/hex-gdd/GDD#d-068">D‑068</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-074">D‑074</a>). <strong>0.4 (2026-11-17):</strong> Made implementable: interact, job mix, pay formula, shift lightning, escalation formula, Garage and boss rules, HUD spec (<a class="decision-ref" href="/hex-gdd/GDD#d-058">D‑058</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-067">D‑067</a>). <strong>0.3 (2026-11-17):</strong> Lightning shield with refill, trial reward budget, driving with drift and nitro (<a class="decision-ref" href="/hex-gdd/GDD#d-050">D‑050</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-057">D‑057</a>). <strong>0.2 (2026-11-17):</strong> Assumption review: <a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-045">D‑045</a> logged, remaining prototype numbers marked <mark class="tune">TUNE</mark>. Trials designed (<a class="decision-ref" href="/hex-gdd/GDD#d-046">D‑046</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-049">D‑049</a>); screens and flow added. <strong>0.1 (2026-11-17):</strong> Docs split into GDD + features/; original GDD archived. Designed run-and-quota, day-cycle-and-storm, packages, damage-and-repair, upgrades, boss-charon; combo cut (<a class="decision-ref" href="/hex-gdd/GDD#d-029">D‑029</a>). Decisions <a class="decision-ref" href="/hex-gdd/GDD#d-023">D‑023</a> to <a class="decision-ref" href="/hex-gdd/GDD#d-029">D‑029</a> logged; <a class="decision-ref" href="/hex-gdd/GDD#d-006">D‑006</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-011">D‑011</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-013">D‑013</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-015">D‑015</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-020">D‑020</a> marked superseded or obsolete. The old 7-day plan, hidden damage and the 3-slot capacity are replaced as described in the decisions.</p>`,11))])}const y=a(o,[["render",c]]);export{m as __pageData,y as default};
